/**
 * 20 题固定问题集（`09` §13.1）的数据集构造器。
 *
 * 只用**函数级生产出口**把数据种进库：`enqueueMaterial` → `claimNextJob` → `runJob`。
 * 不裸写 `case_entity` / `case_relation` / `case_event` / `case_fact_row`
 * （`#006-28`：形状与校验跟着生产走；`#006-35`：走生产出口）。
 *
 * 数据集分两个项目（R-B）：
 * - 主项目 `p-explore`：流水（表格）、话单（表格）、笔录（文本，注入假抽取器）跑完；
 *   第 4 份流水**只入队不认领**。它刻意排在最后入队：`claimNextJob` 认领的是**全局**
 *   FIFO 队列，先入队就会被上一条认领走。
 * - 副项目 `p-explore-pending`：只一份 `待解析流水.xlsx`，只入队不认领 —— 承载
 *   「项目内资金材料未翻译」这个空原因（主项目里也有排队中的材料，两个值必须各自可测）。
 *
 * 时间基准全部写死 `2026-02-xx` / `2026-03-xx`，不依赖 `Date.now()`。
 */
export interface 探索数据集 {
  projectId: string
  /** 副项目：只放一份未解析流水，承载「资金材料未翻译」空原因。 */
  待解析项目: string
  材料: { 流水: string; 话单: string; 笔录: string; 待解析: string }
  账号: Record<"A" | "B" | "D" | "E" | "F" | "G", string>
}

