export async function 种探索数据集(
  db: Queryable,
  文件: Map<string, Uint8Array>,
): Promise<探索数据集> {
  const projectId = "p-explore"
  const 待解析项目 = "p-explore-pending"

  const readFile = async (sourcePath: string) => {
    const bytes = 文件.get(sourcePath)
    if (!bytes) throw new Error(`没有这个文件：${sourcePath}`)
    return bytes
  }

  const 入队 = async (项目: string, 文件名: string, 字节: Uint8Array) => {
    文件.set(`${项目}/${文件名}`, 字节)
    const r = await enqueueMaterial(db, {
      projectId: 项目,
      path: 文件名,
      sourcePath: `${项目}/${文件名}`,
      fileName: 文件名,
      // 每份不同：`createMaterial` 按 `(project_id, fingerprint)` 幂等（`case-store.ts:77-91`）。
      fingerprint: `fp-${文件名}`,
    })
    if (!r.enqueued) throw new Error(`材料没有入队：${文件名}`)
    return r.materialId
  }

  /** 认领并跑一份已入队的材料；队列是全局的，必须核对认领到的就是这一份。 */
  const 跑 = async (materialId: string, 建抽取器?: () => Promise<ReturnType<typeof 建假抽取器>>) => {
    const job = await claimNextJob(db)
    if (!job) throw new Error("队列是空的：上一条用例把作业留在了别的状态？")
    if (job.materialId !== materialId) {
      throw new Error(`认领到别人的作业：期望 ${materialId}，实得 ${job.materialId}`)
    }
    const 结果 = await runJob(db, { readFile, ...(建抽取器 === undefined ? {} : { 建抽取器 }) }, job)
    if (结果 !== "完成") throw new Error(`作业没有跑完：${结果}（材料 ${materialId}）`)
  }

  const 流水 = await 入队(projectId, "资金流水.xlsx", 造工作簿(流水行们, "流水"))
  await 跑(流水)

  const 话单 = await 入队(projectId, "话单.xlsx", 造工作簿(话单行们, "通话"))
  await 跑(话单)

  const 笔录 = await 入队(projectId, "笔录-资金往来.txt", new TextEncoder().encode(笔录正文))
  await 跑(笔录, async () => 建假抽取器(() => 假抽取器回答))

  // ⚠️ 第 4 份必须在**最后**入队，且之后不再 `claimNextJob`（全局 FIFO）。
  const 待解析 = await 入队(projectId, "待解析流水.xlsx", 造工作簿([流水表头], "流水"))

  // 副项目：只入队、不认领。
  await 入队(待解析项目, "待解析流水.xlsx", 造工作簿([流水表头], "流水"))

  return { projectId, 待解析项目, 材料: { 流水, 话单, 笔录, 待解析 }, 账号: { ...账号 } }
}
